const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=s=>s.postOffice?.visits?.find(v=>v.id===s.postOffice.current)||null;
const place=id=>places.find(p=>p.id===id);
const person=id=>recipients.find(p=>p.id===id);
const btn=(attr,text,kind='secondary',disabled=false)=>`<button type="button" class="${kind}" ${attr}${disabled?' disabled':''}>${text}</button>`;
const placeMark={post:'✉',cafe:'♧',orchard:'❧',hill:'✦'};
const welcome='The storm scattered the post. Neighbors are waiting. Pack a parcel. Plan the flight. Fly one step at a time.';
function courier(state,style,carrying=true){
 const identity=postCourierIdentity(state),avatar=avatars.find(a=>a.id===identity.avatar)||avatars[0];
 const face=portrait(avatar.id,true).replace('<svg ','<svg width="116" height="136" style="width:116px;height:136px" ');
 const color=courierPresets.find(c=>c.id===style)?.color||'#655276';
 const hats={witch:'<path d="M-29-32H25L7-66-6-61-12-35Z" fill="#655276" stroke="#433c50" stroke-width="1.5"/><path d="M-10-39H16" stroke="#e9b84a" stroke-width="4"/>',wizard:'<path d="M-25-32H25L0-74Z" fill="#456b99" stroke="#27475e" stroke-width="1.5"/><path d="M-2-57l2-5 2 5 5 2-5 2-2 5-2-5-5-2Z" fill="#f3d78f"/><path d="M-14-38H16" stroke="#f3d78f" stroke-width="3"/>',sorcerer:'<path d="M-27-30Q-34-57 0-68Q34-57 26-30L15-34Q15-52 0-54Q-15-52-16-34Z" fill="#367c79" stroke="#205957" stroke-width="2"/><path d="M14-54l7 2-5 5m-2-7 7-8" stroke="#f3d78f" stroke-width="2" fill="none"/>',rider:'<path d="M-22-33Q-3-52 17-33Z" fill="#abc4da" stroke="#183f39"/><path d="M-21-30H18" stroke="#183f39" stroke-width="3"/>'};
 return `<g class="post-courier" data-courier-avatar="${avatar.id}" data-courier-style="${style}"><path d="M-40 26H39" stroke="#866544" stroke-width="5" stroke-linecap="round"/><path d="M-31 20l-27-8 9 15-9 13 27-9Z" fill="#d9b96e" stroke="#866544" stroke-width="1.5"/><path d="M-9-12Q-30-12-46 14L-15 11 8 24 17 4Z" fill="${color}" stroke="#183f39" stroke-width="1.5"/><path d="M-11 10l15 14h14" fill="none" stroke="#183f39" stroke-width="5" stroke-linecap="round"/><g transform="translate(-25,-47) scale(.43)">${face}</g>${hats[style]||hats.witch}<path d="M7 7l16 6" stroke="${avatar.skin}" stroke-width="5" stroke-linecap="round"/>${carrying?'<rect x="21" y="7" width="20" height="19" rx="2" fill="#d6b77d" stroke="#75593c"/><path d="M22 9l8 7 10-7" fill="none" stroke="#75593c"/>':''}</g>`;
}
