 orchard:'<path d="M-45 19V-15M0 19V-36M44 19V-13" stroke="#866544" stroke-width="7"/><path d="M-70-12Q-72-46-47-48Q-18-49-21-12Z M-29-31Q-35-68 0-71Q35-69 30-31Z M21-10Q16-45 43-47Q73-46 69-10Z" fill="#7ca778"/><g fill="#e9b84a"><circle cx="-48" cy="-30" r="6"/><circle cx="3" cy="-49" r="6"/><circle cx="45" cy="-28" r="6"/></g>',
