export function postMap(state,visit,helper=false){
 const identity=postCourierIdentity(state),order=visit?.order,style=identity.id,location=helper?(visit.helperStep>0?order.helper.destination:'post'):visit?.playback?.location||'post',here=place(location)||places[0];
 const destination=helper?order?.helper.destination:order?.destination;
 const carrying=helper?visit.helperStep<2:visit?.playback?.status!=='delivered';
 const links=places.flatMap((a,i)=>places.slice(i+1).map(b=>`<path d="M${a.x} ${a.y+15}L${b.x} ${b.y+15}" fill="none" stroke="#88aaa5" stroke-width="2" stroke-dasharray="3 8"/>`)).join('');
 const alt=`${helper?'Separate example map. ':''}The ${identity.title.toLowerCase()}, ${identity.pronouns}, is at ${here.name}.${destination?` The parcel goes to ${place(destination)?.name}.`:''} ${carrying?'':' The parcel has been handed over.'} Dotted lines show places you can fly.`;
 return `<figure class="post-map ${helper?'post-help-map':''}"><svg viewBox="0 0 640 390" role="img" aria-label="${esc(alt)}"><path d="M9 95Q35-3 180 20Q310-20 440 20Q615 0 632 103L624 309Q604 390 430 365Q293 394 142 369Q-3 374 9 280Z" fill="#e2eee1"/><path d="M12 280Q230 230 326 293Q430 245 626 270V325Q543 390 326 366Q94 394 13 324Z" fill="#cddfbd"/><path d="M271 0Q303 60 270 120T310 238T293 388" stroke="#abcbd6" stroke-width="24" fill="none"/><path d="M256 143h58M261 151h58" stroke="#fffef9" stroke-width="2"/>${links}${places.map(p=>`${destination===p.id?`<ellipse cx="${p.x}" cy="${p.y+20}" rx="84" ry="32" fill="#f6e5ac" stroke="#9b7c36" stroke-dasharray="5 5"/>`:''}${landmark(p.id,p.x,p.y)}<text x="${p.x}" y="${p.y+52}" text-anchor="middle" fill="#183f39" font-size="16" font-family="Trebuchet MS,Verdana,sans-serif">${esc(p.name)}</text>`).join('')}<g transform="translate(${here.x},${here.y-31}) scale(.84)">${courier(state,style,carrying)}</g>${!carrying&&destination?`<g class="post-handoff" transform="translate(${place(destination).x+47},${place(destination).y+7})"><rect x="-12" y="-8" width="25" height="19" rx="2" fill="#fff4d6" stroke="#75593c"/><path d="M-12-7L0 2 13-7" fill="none" stroke="#75593c"/><circle cx="15" cy="-9" r="10" fill="#397958"/><path d="M10-9l4 4 7-8" stroke="#fffef9" stroke-width="2" fill="none"/></g>`:''}</svg><figcaption>${esc(alt)}</figcaption></figure>`;
}
function courierChoice(state){
 const chosen=postCourierIdentity(state);
 return `<section class="post-courier-picker" aria-labelledby="post-courier-title"><h2 id="post-courier-title">Who will fly today?</h2><div class="post-courier-choice" role="group" aria-label="Choose a courier preset">${courierPresets.map(c=>{const sample={garden:state.garden,postOffice:{courier:c.id,courierAvatar:c.avatar||chosen.avatar,courierPronouns:c.pronouns||chosen.pronouns}};return `<button type="button" class="method ${chosen.id===c.id?'selected':''}" data-post-courier="${c.id}" aria-pressed="${chosen.id===c.id}"><svg viewBox="-65 -80 130 125" aria-hidden="true">${courier(sample,c.id,false)}</svg><strong>${c.label}</strong><small>${c.pronouns||'Your choice of pronouns'}</small></button>`;}).join('')}</div><p class="post-courier-current"><strong>Your courier:</strong> ${esc(chosen.title)} · ${esc(chosen.pronouns)}. Every courier can fly the same routes.</p><details id="post-courier-custom"><summary>Make this character yours</summary><p>Choose a preset above, then change the portrait or pronouns here. These are pretend characters. Your garden character and guide stay as they are.</p><div class="post-custom-choices" role="group" aria-label="Courier portrait">${avatars.map(a=>`<button type="button" class="method" data-post-portrait="${a.id}" aria-pressed="${chosen.avatar===a.id}">${portrait(a.id,true)}${esc(a.name.replace(' explorer',''))} portrait</button>`).join('')}</div><div class="post-custom-choices" role="group" aria-label="Courier pronouns">${courierPronouns.map(value=>`<button type="button" class="method" data-post-pronouns="${value}" aria-pressed="${chosen.pronouns===value}">${value}</button>`).join('')}</div></details></section>`;
}
function packingPicture(math){
 const groups=math.kind==='subtract'?[{label:'Set aside at the counter',count:math.b,reserved:true},{label:'Ready for the parcel',count:math.answer}]:math.pictures.groups;
 return `<div class="post-parcel-picture" role="img" aria-label="${esc(math.kind==='multiply'?`${math.a} equal bundles with ${math.b} ${math.unit} in each`:math.kind==='subtract'?`${math.a} ${math.unit}: ${math.b} set aside and the rest ready to pack`:`${math.a} ${math.unit} and ${math.b} more`)}">${groups.map(g=>`<div class="post-item-group ${g.reserved?'reserved':''}"><span>${esc(g.label)}</span><div>${Array.from({length:g.count},()=>`<span class="post-item" aria-hidden="true">${math.unit?.includes('star')?'✦':math.unit?.includes('ribbon')?'⌁':'▰'}</span>`).join('')}</div>${g.reserved?'<small>Not sent</small>':''}</div>`).join('')}</div>`;
}
function packing(v){
 const m=v.order.math,p=v.packing;
 return `<section class="post-packing" aria-labelledby="post-packing-title"><h2 id="post-packing-title" tabindex="-1">Pack: at the sorting counter</h2><p>${esc(m.prompt)}</p>${packingPicture(m)}${p.packed?`<p class="post-packed" id="post-packing-feedback" role="status">✉ Packed: ${m.answer} ${esc(m.unit)}.</p>${p.supported?`<p class="tiny">Packed together. ${esc(m.explanation)}</p>`:''}`:`<form id="post-packing-form" novalidate><label for="post-packing-input">How many go in the parcel?</label><div class="post-answer-line"><input id="post-packing-input" inputmode="numeric" autocomplete="off" type="text" value="${esc(p.input)}" aria-describedby="post-packing-feedback"><button class="primary" type="submit">Pack my parcel</button></div></form>${btn('data-post-pack-together','Pack together','secondary')}`}${!p.packed?`<p id="post-packing-feedback" role="status">${esc(p.error||p.feedback||'')}</p>`:''}<p class="tiny">You can draw, count, or pack with help.</p>${p.packed?btn('data-post-to-plan','Write my flight plan','primary'):''}</section>`;
}
function routeEditor(v){
 const c=v.composer||{place:'post',recipient:'clover'},full=v.clauses.length>=6;
 const launch=`<div class="post-route-launch">${btn('data-post-to-flight','Fly this route','primary')}<p>Open the map, then fly one instruction at a time. Return here to change your plan.${v.packing.packed?'':' Pack the parcel before flying.'}</p></div>`;
 return `<section class="post-route" aria-labelledby="post-route-title"><h2 id="post-route-title" tabindex="-1">Plan: write your flight plan</h2><p>Choose a stop. Add its words. Tell the courier who gets the parcel.</p>${launch}<div class="post-word-bank"><div><label for="post-place">A place to fly</label><select id="post-place" data-post-composer="place">${places.map(p=>`<option value="${p.id}"${c.place===p.id?' selected':''}>${placeMark[p.id]} ${esc(p.name)}</option>`).join('')}</select><div class="post-bank-actions">${btn('data-post-add="go"',`Go to ${esc(place(c.place)?.name||'Willow Post Office')}`,'secondary',full)}${btn('data-post-add="then"',`Then go to ${esc(place(c.place)?.name||'Willow Post Office')}`,'secondary',full)}${btn('data-post-add="there"','Go there','secondary',full)}</div></div><div><label for="post-recipient">Who gets the parcel?</label><select id="post-recipient" data-post-composer="recipient">${recipients.map(p=>`<option value="${p.id}"${c.recipient===p.id?' selected':''}>${esc(p.name)}</option>`).join('')}</select>${btn('data-post-add="give"',`Give the parcel to ${esc(person(c.recipient)?.name||'Clover')}`,'secondary',full)}</div></div><ol class="post-clauses" aria-label="Your flight plan">${v.clauses.map((id,i)=>`<li class="${v.playback.active===i?'post-active-clause':''}"${v.playback.active===i?' aria-current="step"':''}><span>${esc(clauseText(id))}</span><div>${btn(`data-post-edit="up" data-post-index="${i}" aria-label="Move instruction ${i+1} up"`,'↑','secondary',i===0)}${btn(`data-post-edit="down" data-post-index="${i}" aria-label="Move instruction ${i+1} down"`,'↓','secondary',i===v.clauses.length-1)}${btn(`data-post-edit="remove" data-post-index="${i}" aria-label="Remove instruction ${i+1}"`,'Remove','text-button')}</div></li>`).join('')||'<li class="post-empty">Your words will wait here. Try a stop and a handoff.</li>'}</ol><p class="tiny">${v.clauses.length} of 6 cards used. If you change a card, the courier goes back to the start. Your parcel stays packed.</p>${v.clauses.length?hearButton(v.clauses.map(clauseText).join(' '),'Hear my flight plan'):''}<div class="post-route-launch">${btn('data-post-to-flight','Fly this route','primary')}</div></section>`;
}
function helpView(state,v){
 const h=v.order.helper,done=v.helperStep||0;
 return `<section class="post-example" aria-labelledby="post-example-title"><h2 id="post-example-title" tabindex="-1">Help: Pip’s separate example</h2><p>Our real parcel and flight plan stay waiting. This is a different little delivery.</p>${postMap(state,v,true)}<ol><li${done===1?' class="post-active-clause"':''}>${esc(clauseText(h.clauses[0]))}</li><li${done===2?' class="post-active-clause"':''}>${esc(clauseText(h.clauses[1]))}</li></ol><p role="status">${done===0?'Example courier starts at Willow Post Office.':done===1?`Example courier reached ${esc(place(h.destination)?.name)}.`:`Example parcel reached ${esc(person(h.recipient)?.name)}.`}</p><div class="post-run-buttons">${btn('data-post-help-step="1"','Next example step','secondary',done>=2)}${btn('data-post-help-step="-1"','Previous example step','secondary',done<=0)}${btn('data-post-help-step="reset"','Start example again','text-button')}</div>${hearButton(h.clauses.map(clauseText).join(' '),'Hear Pip’s example')}<p class="tiny">This was Pip’s practice trip. Your own parcel is still waiting.</p><details class="grownup-note"><summary>For grown-ups</summary><p>Pip’s example is recorded as help. It is separate from completing this delivery.</p></details>${btn('data-post-help-return','Return to my waiting task','primary')}</section>`;
}
function brambleArt(resolved=false){return `<svg viewBox="0 0 360 230" role="img" aria-label="Bramble, a girl witch, and her magpie beside the ${resolved?'untangled':'storm-tangled'} ribbon gate"><path d="M20 200Q180 146 340 200" fill="#dce9d0"/><path d="M226 192V52h83v140" stroke="#866544" stroke-width="8" fill="none"/><path d="M226 62Q258 ${resolved?'78':'146'} 309 64M228 79Q268 ${resolved?'93':'30'} 310 87" fill="none" stroke="#daa74b" stroke-width="7"/><path d="M228 105Q258 ${resolved?'120':'25'} 309 106" fill="none" stroke="#8ea9c9" stroke-width="7"/><path d="M73 184l14-64h56l25 64Z" fill="#a66b83" stroke="#61445c" stroke-width="2"/><path d="M93 133l9 36 25-3-2-30" fill="#e9b84a" stroke="#61445c"/><path d="M92 78Q74 107 85 142l16-7 30 1 14-3q10-51-20-61Z" fill="#633e32"/><ellipse cx="115" cy="102" rx="24" ry="28" fill="#b87956"/><path d="M84 81h65l-29-59-14 9Z" fill="#655276" stroke="#433c50" stroke-width="2"/><path d="M104 50l15-6 8 17-18 7Z" fill="#abc4da"/><path d="M95 74h45" stroke="#e9b84a" stroke-width="5"/><circle cx="107" cy="101" r="2" fill="#183430"/><circle cx="124" cy="101" r="2" fill="#183430"/><path d="M108 116q8 7 15-2" fill="none" stroke="#633e32" stroke-width="2"/><path d="M86 142l-22-7m77 8 35-12" stroke="#b87956" stroke-width="8" stroke-linecap="round"/><path d="M166 126q5-20 22-13l12 11-20 10Z" fill="#304d51"/><path d="M173 126l18-5-7 10" fill="#fffef9"/><path d="M193 118l12 4-9 5" fill="#e9b84a"/><circle cx="191" cy="119" r="1.5" fill="#fffef9"/><path d="M93 183v20m49-20v20" stroke="#61445c" stroke-width="8" stroke-linecap="round"/></svg>`;}
function rivalEquation(m){return `${m.a} ${m.kind==='add'?'+':m.kind==='subtract'?'−':'×'} ${m.b} = ${m.answer}`;}
function rivalPicture(m,step=null,splitAt=null){
 const item=color=>`<span class="rival-ribbon ${color}" aria-hidden="true">⌁</span>`;
 const row=(label,blue,gold=0,extra='')=>`<div class="rival-ribbon-group"><span>${esc(label)}</span><div>${Array.from({length:blue},()=>item('blue')).join('')}${Array.from({length:gold},()=>item('gold')).join('')}</div>${extra}</div>`;
 let groups;
 if(m.kind==='add')groups=step!==null&&step>=1?row('Bring both colors together',m.a,m.b):row('Blue ribbons',m.a)+row('Gold ribbons',0,m.b);
 else if(m.kind==='subtract')groups=step===0?row('All the practice ribbons',m.a):row('Reserved for the bow',0,m.b)+row('Ribbons remaining',m.answer);
 else groups=`<div class="rival-array" style="--rival-columns:${m.b}">${Array.from({length:m.a},(_,i)=>`<div class="rival-array-row"><span>${step!==null&&step>=1?`${(i+1)*m.b}`:`${i+1}`}</span><div>${Array.from({length:m.b},()=>`<span class="rival-array-cell ${splitAt!==null&&i>=splitAt?'gold':'blue'}" aria-hidden="true"></span>`).join('')}</div></div>`).join('')}<p>${m.a} ${m.a===1?'bundle':'bundles'} · ${m.b} ${m.b===1?'ribbon':'ribbons'} in each${step!==null&&step>=1?' · left numbers count ribbons so far':' · left numbers label bundles'}</p></div>`;
 const alt=m.kind==='add'?`${m.a} blue ribbons and ${m.b} gold ribbons${step!==null&&step>=1?', brought together':''}`:m.kind==='subtract'?step===0?`${m.a} ribbons before setting any aside`:`${m.a} ribbons: ${m.b} reserved for a bow and the others remaining`:`${m.a} equal ${m.a===1?'bundle':'bundles'} with ${m.b} ${m.b===1?'ribbon':'ribbons'} in each${step!==null&&step>=1?`. Count so far: ${Array.from({length:m.a},(_,i)=>(i+1)*m.b).join(", ")}`:""}`;
 return `<div class="rival-ribbon-picture${m.kind==='multiply'?' rival-array-picture':''}" role="img" aria-label="${esc(alt)}">${groups}</div>`;
}
function brambleChoices(state){
 const b=state.postOffice?.bramble,mode=b?.mode||'mixed',table=b?.table||0;
 return `<details class="post-bramble-choices" id="post-bramble-choices"><summary>Choose the next challenge</summary><p>Your choice starts with the next puzzle.</p><label for="bramble-mode">Kinds of puzzles</label><select id="bramble-mode" data-bramble-mode>${[['mixed','Mixed parcels'],['multiply','Multiplication'],['add','Addition'],['subtract','Subtraction']].map(([id,label])=>`<option value="${id}"${mode===id?' selected':''}>${label}</option>`).join('')}</select><label for="bramble-table">Multiplication table</label><select id="bramble-table" data-bramble-table>${[[0,'All tables: 1–12'],...Array.from({length:12},(_,i)=>[i+1,`${i+1} times table`])].map(([id,label])=>`<option value="${id}"${table===id?' selected':''}>${label}</option>`).join('')}</select><p class="tiny">Table choice applies to multiplication puzzles. Every table is open.</p></details><p class="tiny post-bramble-next">Next challenge: ${esc({mixed:'mixed parcels',multiply:'multiplication',add:'addition',subtract:'subtraction'}[mode])}${['mixed','multiply'].includes(mode)?` · ${table?`${table} times table`:'all tables through 12×12'}`:''}.</p>`;
}
function rivalMethod(r){
 if(r.revision!=='bramble-2'||r.phase!=='resolved'||r.resolution!=='answered')return '';
 return `<fieldset class="post-rival-method"><legend>How did you find it? Optional.</legend><div class="post-run-buttons">${[['recalled','I knew it'],['worked','I worked it out'],['counting','I counted'],['together','We did it together']].map(([id,label])=>`<button type="button" class="method" data-rival-method="${id}" aria-pressed="${r.method===id}">${label}</button>`).join('')}${btn('data-rival-method="clear"','Leave it blank','text-button')}</div><p class="tiny">You can carry on without choosing. Help and retries stay in the notes.</p></fieldset>`;
}
function rivalDecomposition(r){
 if(r.revision!=='bramble-2'||r.task.kind!=='multiply')return '';
 if(r.decompositionStep===null)return btn('data-rival-decomposition="reset"','Build this multiplication in parts','secondary');
 const m=r.task,parts=splitFact(m.a,m.b),first=parts[0][0],step=r.decompositionStep;
 const expression=parts.map(([a,b])=>`${a} × ${b}`).join(' + '),totals=parts.map(([a,b])=>a*b).join(' + ');
 const text=step===0?`Start with ${m.a} equal ${m.a===1?'bundle':'bundles'}. Each holds ${m.b} ${m.b===1?'ribbon':'ribbons'}.`:step===1?parts.length===1?`There is one bundle of ${m.b}. Count its ribbons.`:`Separate ${first} bundles from the other ${parts[1][0]}. ${expression}.`:`${m.a} × ${m.b} = ${expression} = ${totals}${parts.length>1?` = ${m.answer}`:''}.`;
 return `<section class="post-rival-build" aria-labelledby="post-rival-build-title"><h3 id="post-rival-build-title" tabindex="-1">Build this puzzle in parts</h3><p>This picture is help for Bramble’s actual question.</p>${rivalPicture(m,null,step>=1?first:null)}<p role="status">${esc(text)}</p><div class="post-run-buttons">${btn('data-rival-decomposition="-1"','Previous building step','secondary',step===0)}${btn('data-rival-decomposition="1"','Next building step','secondary',step===2)}</div>${hearButton(text,'Hear this building step')}</section>`;
}
function rivalView(state,v){
 const r=v.rival;
 if(!r)return `${brambleChoices(state)}<section class="post-rival-invite"><h3>A rival at the ribbon gate</h3><p>Bramble has a parcel puzzle for you. Meet her, practice first, or keep flying your usual route.</p><div class="post-run-buttons">${btn('data-rival-start','Meet Bramble','secondary')}${btn('data-rival-start="practice"','Practice first','text-button')}</div></section>`;
 const done=['resolved','continued'].includes(r.phase),terminal=['continued','bypassed'].includes(r.phase),m=r.task;
 const line=done?'“You found a way! My gate is free.” Bramble untangles the ribbons and waves you through.':r.phase==='bypassed'?'You took the quiet route. Bramble keeps working on her ribbons, and your parcel stays with you.':'“The storm tied my gate in knots! Help me count the new ribbons, courier?” says Bramble. Her magpie tilts its head.';
 return `<section class="post-rival ${done?'post-rival-resolved':''}" aria-labelledby="post-rival-title"><div class="post-rival-intro">${brambleArt(done)}<div><p class="eyebrow">An optional rival encounter</p><h2 id="post-rival-title" tabindex="-1">Bramble’s ribbon gate</h2><p>Bramble · girl witch · she/her</p><details id="post-bramble-story"><summary>Hear from Bramble</summary><p>${line}</p>${hearButton(line,'Hear Bramble')}</details>${done?'<button type="button" class="text-button" data-film-replay="bramble">Watch the ribbon gate film</button>':''}</div></div><p class="tiny">${v.completed?"Your parcel has arrived. This encounter stays in your delivery notebook.":`Your delivery waits at ${esc(place(v.playback.location)?.name)}. Your parcel and flight plan stay as you left them.`}</p>${r.phase==='practice'?`<div class="post-rival-practice"><h3 id="post-rival-practice-title" tabindex="-1">${r.revision==='bramble-2'?'An example to try together':'A smaller ribbon puzzle'}</h3><p>This is a different example. Bramble’s puzzle stays waiting.</p><p>${esc(m.practice.prompt)}</p>${rivalPicture(m.practice,r.practiceStep)}<p class="post-rival-explanation" role="status">${r.practiceStep===0?'First, lay out the practice supplies.':r.practiceStep===1?m.practice.kind==='add'?'Bring the two sets together. Count on from the first set.':m.practice.kind==='subtract'?`Set ${m.practice.b} aside. Count the ribbons that remain.`:`Each bundle has ${m.practice.b}. Count one equal bundle at a time.`:`${rivalEquation(m.practice)}. ${esc(m.practice.explanation)}`}</p><div class="post-run-buttons">${btn('data-rival-practice-step="-1"','Previous picture','secondary',r.practiceStep===0)}${btn('data-rival-practice-step="1"','Next picture','secondary',r.practiceStep===2)}</div>${hearButton(m.practice.explanation,'Hear this example')}<div class="post-run-buttons">${btn('data-rival-question','Try Bramble’s puzzle','primary')}</div></div>`:r.phase==='question'?`<div class="post-rival-question"><h3 id="post-rival-question-title" tabindex="-1">Ribbons for the gate</h3><p>${esc(m.prompt)}</p>${r.priorFactShown?'<p class="tiny">A matching fact was shown earlier. This puzzle stays open as practice.</p>':''}${rivalPicture(m)}${hearButton(m.prompt,'Hear the ribbon puzzle')}<form id="post-rival-form" novalidate><label for="post-rival-input">How many ribbons?</label><div class="post-answer-line"><input id="post-rival-input" type="text" inputmode="numeric" autocomplete="off" value="${esc(r.input)}" aria-describedby="post-rival-feedback"><button type="submit" class="primary">Try my ribbon count</button></div></form><p id="post-rival-feedback" role="status">${esc(r.feedback)}</p><div class="post-run-buttons">${btn('data-rival-practice',r.revision==='bramble-2'?'Try a different example':'Show a smaller example','secondary')}${btn('data-rival-together','Solve together','text-button')}</div>${rivalDecomposition(r)}</div>`:done?`<p class="post-rival-explanation">${esc(m.explanation)}</p><p>${r.resolution==='together'?'Solved together.':'Ribbon puzzle solved.'} The gate is ready.</p>`:''}${r.phase==='practice'&&r.feedback?`<p role="status">${esc(r.feedback)}</p>`:''}${rivalMethod(r)}${r.phase==='resolved'?`<div class="post-run-buttons">${btn('data-rival-continue',v.completed?'Return to my finished delivery':'Continue my delivery','primary')}${btn('data-rival-next','Another challenge','secondary')}</div>`:!terminal?btn('data-rival-bypass','Take the quiet route','text-button'):btn('data-rival-next','Another challenge','secondary')}${terminal?'<p class="tiny">Saved in your notebook. You can meet Bramble again any time.</p>':''}</section>${brambleChoices(state)}`;
}
const pageTitles={pack:'Pack',plan:'Plan',fly:'Fly',bramble:'Bramble',help:'Help'};
const pageFocus={pack:'#post-packing-title',plan:'#post-route-title',fly:'#post-flight-title',bramble:'#post-bramble-page-title',help:'#post-example-title'};
function routeMaterials(v){
 return `<section class="post-flight-plan" aria-labelledby="post-flight-plan-title"><h3 id="post-flight-plan-title">Your flight plan</h3><ol>${v.clauses.map((id,i)=>`<li${v.playback.active===i?' aria-current="step" class="post-active-clause"':''}>${esc(clauseText(id))}</li>`).join('')||'<li>No instructions yet. Choose Plan to add a stop and a handoff.</li>'}</ol>${v.clauses.length?hearButton(v.clauses.map(clauseText).join(' '),'Hear my flight plan'):''}${btn('data-post-edit-route','Change my flight plan','secondary')}</section>`;
}
function deliveryFlight(state,v){
 const p=v.playback;
 return `<section class="post-flight" aria-labelledby="post-flight-title"><h2 id="post-flight-title" tabindex="-1">Fly: follow one instruction</h2><p>Press Fly the next instruction. Then look where the courier went. Your plan stays beside the map.</p><p class="post-flight-status" role="status" tabindex="-1">${esc(p.feedback||(v.packing.packed?(v.clauses.length?'Parcel packed. Ready to fly your next instruction.':'Parcel packed. Write a flight plan when you are ready.'):`Ready at ${place(p.location)?.name}. Pack the parcel and write a flight plan.`))}</p><div class="post-run-buttons">${rivalBlocks(v)?btn('data-rival-focus','Return to Bramble’s gate','primary'):!v.packing.packed?btn('data-post-to-packing','Pack the parcel first','primary'):p.status==='delivered'?btn('data-post-restart','Replay this flight','secondary'):['clarify','ended'].includes(p.status)?btn('data-post-edit-route','Change my flight plan','primary'):btn('data-post-step','Fly the next instruction','primary')}${p.status!=='delivered'?btn('data-post-restart','Back to the start','secondary'):''}</div><div class="post-flight-work">${postMap(state,v)}${routeMaterials(v)}</div>${v.completed&&p.status!=='delivered'?'<p class="tiny">You delivered this one before. Fly it again just for fun.</p><details class="grownup-note"><summary>For grown-ups</summary><p>Replaying a delivered visit adds no new completed delivery.</p></details>':''}${p.status==='clarify'||p.status==='ended'?'<p>Keep your parcel. Change the flight plan, or return to the start to try again.</p>':''}${p.log.length?`<details id="post-flight-log"><summary>Our flight log</summary><ol>${p.log.map(line=>`<li>${esc(line)}</li>`).join('')}</ol></details>`:''}${!v.rival?`<section class="post-rival-invite"><h3>A rival at the ribbon gate</h3><p>Bramble has an optional parcel puzzle. Your delivery will wait.</p>${btn('data-rival-start','Meet Bramble','secondary')}</section>`:btn('data-post-page="bramble"','Visit Bramble','secondary')}${p.status==='delivered'?`<section class="post-delivered" aria-label="A delivery completed"><span aria-hidden="true">✉ ✓</span><h2>${esc(person(v.order.recipient)?.name||'A neighbor')} has the parcel.</h2><p>You can replay, try a new flight plan, or choose another delivery.</p>${btn('data-post-next','Choose the next delivery','primary')}<a class="secondary" href="#post/choose">See all six orders</a></section>`:''}</section>`;
}
function investigation(state,v){
 if(v.closed)return `<section class="post-sheet"><h2>An earlier delivery is kept</h2><p>${esc(v.closedReason)}</p><a class="primary" href="#post/choose">Choose a fresh delivery</a><a class="secondary" href="#notes">Read the kept work</a></section>`;
 const o=v.order,p=v.playback,page=postOfficeView(v);
 const body=page==='pack'?packing(v):page==='plan'?routeEditor(v):page==='fly'?deliveryFlight(state,v):page==='help'?helpView(state,v):`<section class="post-bramble-page" aria-labelledby="post-bramble-page-title"><h2 id="post-bramble-page-title" tabindex="-1">Bramble: a puzzle at the ribbon gate</h2><p>Your parcel stays safe while you try a puzzle. You can return to the delivery at any time.</p>${btn('data-post-to-flight','Return to my delivery','secondary')}${rivalView(state,v)}</section>`;
 return `<section class="post-order" aria-labelledby="post-order-title"><div class="post-order-stamp" aria-hidden="true">${esc(person(o.recipient)?.emoji||'✉')}</div><div><h2 id="post-order-title" tabindex="-1">${esc(o.title)}</h2><p>${esc(o.request)}</p><p><strong>Deliver to:</strong> ${esc(person(o.recipient)?.name)} at ${esc(place(o.destination)?.name)}.</p><p class="post-parcel-status"><strong>Parcel:</strong> ${v.packing.packed?`packed (${o.math.answer} ${esc(o.math.unit)})`:'waiting to be packed'} · <strong>Courier:</strong> ${esc(place(p.location)?.name)}${p.status==='delivered'?' · handed over':''}.</p>${hearButton(o.request,'Hear this order')}</div></section><nav class="post-step-links" aria-label="Delivery pages">${Object.entries(pageTitles).map(([id,label],i)=>btn(`data-post-page="${id}"${page===id?' aria-current="step"':''}`,`${i<3?`${i+1}. `:''}${label}`,page===id?'primary':'secondary')).join('')}</nav><div class="post-task-page" data-post-current-page="${page}">${body}</div><details class="post-locations" id="post-neighbor-locations"><summary>Where the neighbors are</summary>${places.map(t=>`<p><strong>${esc(t.name)}</strong>: ${recipients.filter(r=>v.recipientLocations[r.id]===t.id).map(r=>`${esc(r.emoji)} ${esc(r.name)}`).join(', ')||'the sorting counter'}</p>`).join('')}</details><details class="post-optional" id="post-extra-tools"><summary>Optional ideas</summary><details id="post-prediction"><summary>Where might this plan leave us?</summary><p>Just for fun. You can change your mind.</p><div class="post-prediction-choices">${places.map(t=>`<button type="button" class="method ${v.prediction===t.id?'selected':''}" data-post-prediction="${t.id}" aria-pressed="${v.prediction===t.id}">${esc(t.name)}</button>`).join('')}${btn('data-post-prediction="clear"','Leave it blank','text-button')}</div>${v.prediction?`<p class="tiny">${v.predictionAfterSupport?'You picked this after flying or getting help.':'You picked this before flying or getting help.'}</p>`:''}</details><details><summary>A paper or talking idea</summary><p>Give someone directions to a pretend parcel. Ask them to follow exactly what you said. Which words would you change?</p><p class="tiny">Just for fun, on paper or out loud.</p></details></details><details id="post-reading" class="grownup-note"><summary>For grown-ups</summary><p>How did we read this delivery?</p><div class="post-prediction-choices">${[['unobserved','Reading not observed'],['together','Read together'],['independent','Reported read independently']].map(([id,text])=>`<button type="button" class="method ${v.reading===id?'selected':''}" data-post-reading="${id}" aria-pressed="${v.reading===id}">${text}</button>`).join('')}</div><p class="tiny">Narration and help stay in the record. This report does not measure decoding or fluency.</p></details>`;
}
function catalog(){return `<section class="post-catalog"><h2>The sorting board</h2><p>Pick any order. Earlier parcels stay waiting while you explore another.</p><div>${deliveries.map(o=>`<article><span aria-hidden="true">${esc(person(o.recipient)?.emoji||'✉')}</span><h3>${esc(o.title)}</h3><p>${esc(person(o.recipient)?.name)} is at ${esc(place(o.destination)?.name)}.</p>${btn(`data-post-start="${o.id}"`,'Take this delivery','primary')}</article>`).join('')}</div></section>`;}
export function postOfficePage(state,slug){
 const v=current(state),xs=state.postOffice?.visits||[],hub=slug==='choose'||!v;
 return `<div class="post-office-page"><header class="page-heading"><a class="back" href="#home"><span aria-hidden="true">←</span> Take a break</a><h1>Willow Post Office</h1><p>Parcels to pack. A broom to borrow. Neighbors to find.</p>${hearButton(welcome,'Hear our delivery story')}</header>${hub?courierChoice(state):`<details class="post-active-courier" id="post-active-courier"><summary>Your courier · change character</summary>${courierChoice(state)}</details>`}${state.postOffice?.kept?'<p class="storage-warning" role="status">An earlier Post Office save could not be resumed. Its exact work is kept in <a href="#notes">Grown-up notes</a> and your download. New deliveries start separately.</p>':''}${hub?`<section class="post-welcome">${postMap(state,null)}<div><h2>The post must fly.</h2><p>The storm scattered our mail. Pip sorts the parcels. Dot checks the addresses. You can help the neighbors get what they need.</p><ol><li>Read an order and pack a parcel.</li><li>Build a flight plan with word cards.</li><li>Fly one instruction, then look and revise.</li></ol>${v?btn(`data-post-resume="${esc(v.id)}"`,'Continue the waiting delivery','primary'):''}</div></section>${ferryEntry()}${hatsEntry()}${codesEntry()}${catalog()}${sortingEntry()}${doubleEntry()}`:`<div class="post-game-layout"><div>${investigation(state,v)}</div><details class="post-guide"><summary>A word from your guide</summary>${guideRail(state,'{guide} says, “Our words have a job to do. Let’s try them, watch closely, and change anything that needs a clearer idea.”')}</details></div>`}${xs.length?`<details class="panel" id="post-saved-visits"><summary>Our delivery notebook (${xs.length} kept)</summary><details class="grownup-note"><summary>For grown-ups</summary><p>Latest 24 visits. Replaying the same visit adds no new completed delivery.</p></details>${[...xs].reverse().map(x=>`<p>${btn(`data-post-resume="${esc(x.id)}"`,`${esc(x.order?.title||x.id)}: ${x.closed?'kept earlier work':x.completed?'delivered before':'waiting'}`)}</p>`).join('')}</details>`:''}<p class="post-switch"><a class="secondary" href="#post/choose">Choose any order</a><a class="secondary" href="#post/lost-and-found">The Lost and Found Board</a><a class="secondary" href="#workshop/maps">Make a walking map</a><a class="secondary" href="#workshop/clock">Preparation Clock</a><a class="secondary" href="#workshop/windows">Two Windows: read two tellers</a><a class="text-button" href="#home">Take a break</a></p>${hub?learningInvitations('post'):`<details class="post-onward"><summary>Explore somewhere else</summary>${learningInvitations('post')}</details>`}</div>`;
}
function adaptiveBrambleNotes(state){
 const b=state.postOffice?.bramble;if(!b)return '';
 return `<details class="panel"><summary>Bramble’s changing challenges (${b.history.length} rounds kept)</summary><p>Latest 96 finished rounds, in finish order. Each task is an observation, not a fact-mastery or independent-recall claim. Bypasses are not misses. Method reports and support stay distinct. Pending rounds stay with their deliveries.</p><p>Next round ID: ${b.nextRound}. Choices: ${esc(b.mode)}, ${b.table?`${b.table} times table`:'all tables'}.</p>${b.history.slice().reverse().map(r=>`<section><h3>Round ${r.id} · ${esc(r.phase)}</h3><p>${esc(r.task.prompt)}</p><p>Selection: ${esc(r.reason)}. Resolution: ${esc(r.resolution||'none')}. Method report: ${esc(r.method||'unreported')}. Related fact shown earlier: ${r.priorFactShown?'yes':'not recorded'}. Support: ${r.supported?'yes':'no'}. Narration requested: ${r.audioRequested?'yes':'no'}. Decomposition opened: ${r.decompositionStep!==null?'yes':'no'}.</p><p>Attempts: ${esc(r.attempts.map(a=>`${a.input} (${a.correct?'fits':'another look'}; ${a.afterSupport?'after support':'before support'})`).join(', ')||'none')}.</p></section>`).join('')}</details>`;
}
export function postOfficeNotes(state){
 const p=state.postOffice,xs=p?.visits||[];if(!p||!xs.length&&!p.kept&&!p.bramble)return '';
 return `${adaptiveBrambleNotes(state)}<details class="panel"><summary>Willow Post Office (${xs.length} visits kept)</summary><p>Finite authored delivery practice: packing numbers, structured route composition, literal execution and revision. This does not establish independent decoding, free writing, programming proficiency or fact mastery. Up to 24 visits and 24 run checks per visit are retained. Support, reading reports and math attempts stay distinct.</p>${p.kept?`<h3>Earlier save kept exactly</h3><p>${esc(p.kept.reason)}</p><code class="post-kept-data">${esc(JSON.stringify(p.kept.payload))}</code>`:''}${xs.map(v=>`<section><h3>${esc(v.order?.title||v.id)}${v.closed?' (closed work)':''}</h3>${v.closed?`<p>${esc(v.closedReason)}</p><code class="post-kept-data">${esc(JSON.stringify(v))}</code>`:`<p>${esc(v.order.request)}</p><p>Route: ${esc(v.clauses.map(clauseText).join(' ')||'not composed')}. Composition edits: ${v.revisions}. Completed once: ${v.completed?'yes':'no'}.</p><p>Packing attempts: ${esc(v.packing.attempts.map(a=>`${a.input} (${a.correct?'count fits':'another look'})`).join(', ')||'none')}. Packing support: ${v.packing.supported?'yes':'no'}. Current input: ${esc(v.packing.input)}. Parcel packed: ${v.packing.packed?'yes':'no'}.</p><p>Reading: ${esc(v.reading)}. Narration requested: ${v.support.audioRequested?'yes':'no'} (playback not verified). Separate example opened: ${v.support.helper?'yes':'no'}. Prediction: ${esc(v.prediction||'none')}${v.predictionAfterSupport?' (after execution or support)':''}.</p><p>Waiting at ${esc(place(v.playback.location)?.name)}; next instruction index ${v.playback.cursor}; ${esc(v.playback.status)}.</p>${v.rivalLegacy?`<details><summary>Earlier authored Bramble encounter</summary><pre class="post-kept-data">${esc(JSON.stringify(v.rivalLegacy,null,2))}</pre></details>`:''}${v.rival?`<details><summary>Bramble’s ribbon puzzle: ${esc(v.rival.phase)}</summary><p>Selection: ${esc(v.rival.reason)}. ${esc(v.rival.task.prompt)}${v.rival.revision==='bramble-2'?` Round ${v.rival.id}. Method report: ${esc(v.rival.method||'unreported')}. Decomposition opened: ${v.rival.decompositionStep!==null?'yes':'no'}.`:''}</p><p>Resolution: ${esc(v.rival.resolution||'none')}. Related fact shown earlier: ${v.rival.priorFactShown?'yes':'not recorded'}. Support opened: ${v.rival.supported?'yes':'no'}. Narration requested: ${v.rival.audioRequested?'yes':'no'}. Practice picture: ${v.rival.practiceStep}.</p><p>Current input: ${esc(v.rival.input)}. Attempts: ${esc(v.rival.attempts.map(a=>`${a.input} (${a.correct?'fits':'another look'}; ${a.afterSupport?'after support':'before support'})`).join(', ')||'none')}.</p><p>These are separate supplies puzzles, not packing or independent recall evidence. Bypassing is not an incorrect answer.</p></details>`:''}<details><summary>Route checks (${v.checks.length})</summary><pre class="post-kept-data">${esc(JSON.stringify(v.checks,null,2))}</pre></details>`}</section>`).join('')}</details>`;
}
export function bindPostOffice(state,{save,render,navigate,focus}){
 const redraw=target=>{const open=[...document.querySelectorAll('.post-office-page details[id][open]')].map(d=>d.id);save();render();for(const id of open){const d=document.getElementById(id);if(d)d.open=true;}if(target)focus(target);};
 const openPage=page=>{if(page==='help')setPostSupport(state,'helper');setPostPage(state,page);};
 const bind=(selector,fn,target)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{fn(b);redraw(target);}));
 document.querySelectorAll('[data-post-start]').forEach(b=>b.addEventListener('click',()=>{startPostOffice(state,b.dataset.postStart);save();navigate('#post');focus('#post-order-title');}));
 document.querySelectorAll('[data-post-resume]').forEach(b=>b.addEventListener('click',()=>{resumePostOffice(state,b.dataset.postResume);save();navigate('#post');}));
 bind('[data-post-courier]',b=>setPostCourier(state,b.dataset.postCourier),'.post-courier-choice [aria-pressed="true"]');
 bind('[data-post-portrait]',b=>setPostCourierPortrait(state,b.dataset.postPortrait),'[data-post-portrait][aria-pressed="true"]');
 bind('[data-post-pronouns]',b=>setPostCourierPronouns(state,b.dataset.postPronouns),'[data-post-pronouns][aria-pressed="true"]');
 bind('[data-rival-start]',b=>{startAdaptiveRival(state,b.dataset.rivalStart==='practice');setPostPage(state,'bramble');},'#post-bramble-page-title');
 bind('[data-rival-next]',()=>nextRivalChallenge(state),'#post-rival-question-title');
 bind('[data-rival-method]',b=>setRivalMethod(state,b.dataset.rivalMethod==='clear'?null:b.dataset.rivalMethod),'#post-rival-title');
 bind('[data-rival-decomposition]',b=>stepRivalDecomposition(state,b.dataset.rivalDecomposition==='reset'?'reset':Number(b.dataset.rivalDecomposition)),'#post-rival-build-title');
 document.querySelector('[data-bramble-mode]')?.addEventListener('change',event=>{setBrambleMode(state,event.target.value);redraw('#bramble-mode');});
 document.querySelector('[data-bramble-table]')?.addEventListener('change',event=>{setBrambleTable(state,Number(event.target.value));redraw('#bramble-table');});
 bind('[data-rival-practice]',()=>openRivalPractice(state),'#post-rival-practice-title');
 bind('[data-rival-practice-step]',b=>stepRivalPractice(state,Number(b.dataset.rivalPracticeStep)),'#post-rival-practice-title');
 bind('[data-rival-question]',()=>returnRivalQuestion(state),'#post-rival-question-title');
 bind('[data-rival-together]',()=>solveRivalTogether(state),'#post-rival-title');
 bind('[data-rival-bypass]',()=>{bypassRival(state);setPostPage(state,'fly');},'#post-flight-title');
 bind('[data-rival-continue]',()=>{continueRival(state);setPostPage(state,'fly');},'#post-flight-title');
 bind('[data-rival-focus]',()=>setPostPage(state,'bramble'),'#post-bramble-page-title');
 document.querySelector('#post-rival-input')?.addEventListener('input',event=>{setRivalInput(state,event.target.value);save();});
 document.querySelector('#post-rival-form')?.addEventListener('submit',event=>{event.preventDefault();submitRival(state);redraw(current(state)?.rival?.phase==='practice'?'#post-rival-practice-title':'#post-rival-title');});

 document.querySelectorAll('[data-post-composer]').forEach(el=>el.addEventListener('change',()=>{setPostComposer(state,el.dataset.postComposer,el.value);redraw(`#${el.id}`);}));
 bind('[data-post-add]',b=>{const v=current(state),kind=b.dataset.postAdd,c=v.composer;appendPostClause(state,kind==='there'?'there':`${kind}:${kind==='give'?c.recipient:c.place}`);},'.post-clauses');
 bind('[data-post-edit]',b=>editPostClause(state,Number(b.dataset.postIndex),b.dataset.postEdit),'.post-clauses');
 document.querySelector('#post-packing-input')?.addEventListener('input',event=>{setPostPackingInput(state,event.target.value);save();});
 document.querySelector('#post-packing-form')?.addEventListener('submit',event=>{event.preventDefault();setPostPage(state,'pack');submitPostPacking(state);redraw('#post-packing-feedback');});
 bind('[data-post-pack-together]',()=>{setPostPage(state,'pack');packPostTogether(state);},'#post-packing-feedback');
 bind('[data-post-step]',()=>stepPostRoute(state),'.post-flight-status');
 bind('[data-post-restart]',()=>restartPostRoute(state),'.post-flight-status');
 bind('[data-post-to-packing]',()=>setPostPage(state,'pack'),'#post-packing-title');
 bind('[data-post-to-plan]',()=>setPostPage(state,'plan'),'#post-route-title');
 bind('[data-post-to-flight]',()=>setPostPage(state,'fly'),'#post-flight-title');
 bind('[data-post-edit-route]',()=>setPostPage(state,'plan'),'#post-route-title');
 document.querySelectorAll('[data-post-page]').forEach(b=>b.addEventListener('click',()=>{const page=b.dataset.postPage;openPage(page);redraw(pageFocus[page]);}));
 document.querySelectorAll('[data-post-help-return]').forEach(b=>b.addEventListener('click',()=>{returnFromPostHelp(state);redraw(pageFocus[postOfficeView(current(state))]);}));
 bind('[data-post-prediction]',b=>setPostPrediction(state,b.dataset.postPrediction==='clear'?null:b.dataset.postPrediction),'#post-prediction');
 bind('[data-post-reading]',b=>setPostReading(state,b.dataset.postReading),'#post-reading');
 bind('[data-post-help]',()=>openPage('help'),'#post-example-title');
 bind('[data-post-help-step]',b=>stepPostHelp(state,b.dataset.postHelpStep==='reset'?'reset':Number(b.dataset.postHelpStep)),'#post-example-title');
 document.querySelectorAll('[data-post-next]').forEach(b=>b.addEventListener('click',()=>{const v=current(state),i=deliveries.findIndex(o=>o.id===v?.order?.id);startPostOffice(state,deliveries[(i+1)%deliveries.length].id);save();navigate('#post');focus('#post-order-title');}));
 document.querySelectorAll('.post-office-page [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(b.closest('.post-rival'))noteRivalAudio(state);else setPostSupport(state,'audioRequested');save();}));
}
